// Vérification HMAC — même motif que RAG - Ingest (RFC-099).
// Ce webhook frappe des jetons avec la clé système : sans signature, l'URL
// suffirait à ouvrir des sessions facturées sur notre compte.
const input = $input.first().json;
const headers = input.headers || {};
const computed = String(input.computed_signature || '').toLowerCase();
const brut = headers['x-webhook-signature'] || headers['X-Webhook-Signature'] || '';
// Le préfixe est normalisé AVANT d'être retiré : un « SHA256= » en
// majuscules serait sinon rejeté comme signature invalide alors qu'elle
// est correcte — une erreur qui accuse le mauvais coupable.
const fourni = String(brut).toLowerCase().replace('sha256=', '');

if (!brut) {
  return { hmac_valid: false, error: 'En-tête X-Webhook-Signature absent', http_code: 401, body: input.body, headers };
}
if (!computed) {
  return { hmac_valid: false, error: 'HMAC non calculé (vérifier N8N_REALTIME_WEBHOOK_SECRET)', http_code: 500, body: input.body, headers };
}
if (fourni.length !== computed.length || fourni !== computed) {
  return { hmac_valid: false, error: 'Signature HMAC invalide', http_code: 401, body: input.body, headers };
}
return { hmac_valid: true, body: input.body, headers };

// Contrôle du modèle demandé, avant de frapper quoi que ce soit.
//
// ⚠️ OpenAI ne valide PAS le modèle à la frappe : vérifié, un POST
// /v1/realtime/client_secrets avec « modele-invente-42 » rend 200 et un jeton.
// La vérification est donc à notre charge, sinon un modèle inexistant échoue
// plus tard, à la poignée de main WebSocket, chez le client et sans cause
// lisible.
//
// La liste vient de $env, sans repli : ce webhook frappe des jetons avec la clé
// SYSTÈME. Une liste implicite ou un défaut permissif ferait de lui un
// distributeur de sessions facturées sur notre compte.
const body = $input.first().json.body || {};

const autorises = String($env.REALTIME_MODELS || '')
  .split(',').map(s => s.trim()).filter(Boolean);

if (!autorises.length) {
  return [{ json: { valide: false, erreur: {
    code: 503,
    message: 'REALTIME_MODELS non configuré — aucun modèle temps réel autorisé',
    status: 'NOT_CONFIGURED' } } }];
}

const model = String(body.model || '').trim();
if (!model) {
  return [{ json: { valide: false, erreur: {
    code: 400, message: 'Le paramètre "model" est requis', status: 'BAD_REQUEST' } } }];
}
if (autorises.indexOf(model) === -1) {
  return [{ json: { valide: false, erreur: {
    code: 422,
    message: 'Modèle non autorisé pour le temps réel : ' + model,
    status: 'MODEL_NOT_ALLOWED',
    allowed: autorises } } }];
}

// Durée bornée : un jeton à longue vie annule l'intérêt d'un jeton éphémère.
// 600 s est le défaut d'OpenAI ; on refuse d'aller au-delà de 1800.
let secondes = parseInt(body.expires_after_seconds, 10);
if (isNaN(secondes) || secondes <= 0) secondes = 600;
secondes = Math.min(secondes, 1800);

return [{ json: { valide: true, model: model, secondes: secondes } }];

// Relais de la charge OpenAI, telle quelle.
//
// Contrat arrêté avec l'API : on rend `value`, `expires_at` et `session`
// sans enveloppe maison — le client parle ensuite directement à OpenAI, il a
// besoin de la forme d'OpenAI, pas de la nôtre.
const rep = $input.first().json;

// Avec onError=continueRegularOutput, un échec n'émet pas {statusCode, body} :
// le statut réel est enfoui dans le message sous la forme « 401 - {...} ».
let statut = rep?.statusCode;
if (statut === undefined) {
  const brut = String(rep?.error?.message || rep?.message || '');
  const m = brut.match(/(\d{3})\s*-\s*/);
  statut = m ? parseInt(m[1], 10) : ((rep?.error || rep?.code) ? 502 : 200);
}

if (statut >= 400 || rep?.error !== undefined) {
  return [{ json: { success: false, error: {
    code: statut,
    message: String(rep?.error?.message || rep?.message || "OpenAI n'a pas frappé de jeton"),
    status: 'MINT_FAILED' } } }];
}

const corps = rep?.body ?? rep;
if (!corps || !corps.value) {
  // 200 sans jeton : le pire cas. On refuse de le présenter comme un succès.
  return [{ json: { success: false, error: {
    code: 502,
    message: 'Réponse acceptée mais sans jeton',
    status: 'NO_TOKEN' } } }];
}
return [{ json: corps }];
